<?php
namespace App\Http\Controllers;
use App\Http\Requests\BuscarCitaRequest; use App\Http\Requests\CitaRequest; use App\Services\CitaService; use Illuminate\Http\Response;
class CitaController extends Controller {public function __construct(private CitaService $service){} public function index(BuscarCitaRequest $r){return response()->json($this->service->listar($r->validated()));} public function buscar(BuscarCitaRequest $r){return response()->json($this->service->buscar($r->validated()));} public function catalogos(){return response()->json($this->service->catalogos());} public function show(string $id){return response()->json(['data'=>$this->service->obtener($id)]);} public function store(CitaRequest $r){return response()->json(['data'=>$this->service->crear($r->validated())],201);} public function update(CitaRequest $r,string $id){return response()->json(['data'=>$this->service->actualizar($id,$r->validated(),$r->isMethod('PUT'))]);} public function destroy(string $id):Response{$this->service->eliminar($id);return response()->noContent();}}
